    "value":  "\u003c!doctype html\u003e\u003chtml lang=\"en\"\u003e\u003chead\u003e\u003cmeta charset=\"utf-8\"\u003e\u003cmeta name=\"viewport\" content=\"width=device-width,initial-scale=1\"\u003e\n\u003ctitle\u003eAdmin Login | VOCO Rooftop\u003c/title\u003e\u003cmeta name=\"robots\" content=\"noindex\"\u003e\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\"\u003e\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin\u003e\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800\u0026family=Playfair+Display:wght@800\u0026family=Jost:wght@500\u0026display=swap\" rel=\"stylesheet\"\u003e\n\u003cstyle\u003e\n*{box-sizing:border-box;margin:0}\nbody{min-height:100vh;display:grid;place-items:center;padding:24px;background:#FFFFEC;color:#111;font-family:\"Plus Jakarta Sans\",system-ui,sans-serif}\n.card{width:100%;max-width:340px;padding:30px 32px 28px;border-radius:26px;background:#fff;border:1px solid #e4e4d4;box-shadow:0 8px 28px rgba(27,51,38,.08)}\n.wm{display:flex;flex-direction:column;align-items:center;line-height:1;margin-bottom:14px}\n.wm b{font:800 38px \"Playfair Display\",Georgia,serif;color:#1B3326}\n.wm i{font:500 8px Jost,sans-serif;font-style:normal;color:#B89C6E;letter-spacing:.7em;margin:5px -.7em 0 0}\nh1{text-align:center;font-size:20px;font-weight:800}\n.sub{text-align:center;margin:8px 0 24px;font-size:11px;color:#8b95a5}\nlabel{display:block;font-size:11px;font-weight:700;margin-bottom:7px}\n.f{position:relative;margin-bottom:18px}\n.f svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:15px;height:15px;stroke:#9aa0a6;fill:none;stroke-width:1.8}\ninput{width:100%;height:38px;padding:0 12px 0 36px;border:1px solid #dcdccb;border-radius:10px;background:#f4f4ee;font:inherit;font-size:12px;color:#111}\ninput:focus{outline:2px solid #1B3326;outline-offset:1px;background:#fff}\n.go{width:100%;height:38px;margin-top:6px;border:0;border-radius:99px;background:#1B3326;color:#fff;font:700 12px inherit;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}\n.go:hover{background:#244533}.go:disabled{opacity:.6}\n.err{min-height:18px;margin-top:12px;font-size:12px;color:#c0392b;text-align:center}\n.warn{margin-top:4px;font-size:11px;color:#8a6d3b;line-height:1.5;text-align:center}\n.back{display:block;margin-top:14px;text-align:center;font-size:11px;color:#8b95a5;text-decoration:none}.back:hover{color:#1B3326}\n\u003c/style\u003e\u003c/head\u003e\u003cbody\u003e\n\u003cmain class=\"card\"\u003e\n\u003cdiv class=\"wm\"\u003e\u003cb\u003eVOCO\u003c/b\u003e\u003ci\u003eROOFTOP\u003c/i\u003e\u003c/div\u003e\n\u003ch1\u003eAdmin Panel\u003c/h1\u003e\u003cp class=\"sub\"\u003eSign in to access your dashboard\u003c/p\u003e\n\u003cform id=\"f\"\u003e\n\u003clabel for=\"e\"\u003eEmail Address\u003c/label\u003e\n\u003cdiv class=\"f\"\u003e\u003csvg viewBox=\"0 0 24 24\"\u003e\u003crect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/\u003e\u003cpath d=\"M3 7l9 6 9-6\"/\u003e\u003c/svg\u003e\u003cinput id=\"e\" type=\"email\" placeholder=\"admin@vocorooftop.com\" autocomplete=\"username\" required autofocus\u003e\u003c/div\u003e\n\u003clabel for=\"p\"\u003ePassword\u003c/label\u003e\n\u003cdiv class=\"f\"\u003e\u003csvg viewBox=\"0 0 24 24\"\u003e\u003crect x=\"5\" y=\"11\" width=\"14\" height=\"9\" rx=\"2\"/\u003e\u003cpath d=\"M8 11V8a4 4 0 0 1 8 0v3\"/\u003e\u003c/svg\u003e\u003cinput id=\"p\" type=\"password\" placeholder=\"â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢\" autocomplete=\"current-password\" required\u003e\u003c/div\u003e\n\u003cbutton class=\"go\" id=\"b\"\u003eSign In \u003csvg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\"\u003e\u003cpath d=\"M5 12h14M13 6l6 6-6 6\"/\u003e\u003c/svg\u003e\u003c/button\u003e\n\u003cp class=\"err\" id=\"m\" role=\"alert\"\u003e\u003c/p\u003e\u003c/form\u003e\n\u003cp class=\"warn\"\u003e{{WARN}}\u003c/p\u003e\n\u003ca class=\"back\" href=\"/\"\u003eâ† Back to website\u003c/a\u003e\n\u003c/main\u003e\n\u003cscript\u003e\nconst m=document.getElementById(\u0027m\u0027),b=document.getElementById(\u0027b\u0027);\ndocument.getElementById(\u0027f\u0027).onsubmit=async ev=\u003e{ev.preventDefault();b.disabled=true;m.textContent=\u0027\u0027;\n try{const r=await fetch(\u0027/api/login\u0027,{method:\u0027POST\u0027,headers:{\u0027content-type\u0027:\u0027application/json\u0027},body:JSON.stringify({email:document.getElementById(\u0027e\u0027).value,password:document.getElementById(\u0027p\u0027).value})});\n  if(r.ok)location.href=\u0027/admin\u0027;else m.textContent=r.status===401?\u0027Incorrect email or password.\u0027:(await r.text());}\n catch(x){m.textContent=\u0027Could not reach the server.\u0027}b.disabled=false};\n\u003c/script\u003e\u003c/body\u003e\u003c/html\u003e\n",
